/bin/bash -lc "python3 - << 'PY'
import pandas as pd
from datetime import datetime
import re

df = pd.read_excel('mixed_units_register.xlsx', sheet_name='Disbursement Register', header=5)
# clean columns
df = df[['Disbursement Date','Programme','Amount']].copy()

def parse_date(s):
    if pd.isna(s):
        return None
    s = str(s).strip()
    for fmt in ('%Y-%m-%d','%d/%m/%Y','%d %b %Y','%d %B %Y'):
        try:
            return datetime.strptime(s, fmt).date()
        except:
            pass
    # try day month year with 1-2 digit day
    # fallback using pandas to_datetime
    try:
        return pd.to_datetime(s, dayfirst=True, errors='coerce').date()
    except:
        return None

def parse_amount(s):
    if pd.isna(s):
        return 0
    s = str(s).strip()
    if s in ('','-','NA','NaN'):
        return 0
    # remove ₹ and commas
    s = s.replace('₹','').replace(',','').strip()
    # handle patterns like 1.2 L, 2.5 lakh, 45k, 1 Cr
    # normalize
    s_low = s.lower()
    # match number
    m = re.match(r'"'^([0-9]*'"\\.?[0-9]+)\\s*([a-zA-Z]*)"'$'"', s_low)
    if not m:
        # maybe just number
        try:
            return float(s)
        except:
            return 0
    num = float(m.group(1))
    unit = m.group(2)
    if unit in ('',''):
        mult = 1
    elif unit in ('k',''):
        mult = 1000
    elif unit in ('l','lakh'):
        mult = 100000
    elif unit in ('cr','crore'):
        mult = 10000000
    else:
        # unknown
        mult = 1
    return num * mult

df['date_parsed'] = df['Disbursement Date'].apply(parse_date)
df['amount_parsed'] = df['Amount'].apply(parse_amount)

# filter
start = datetime(2025,4,1).date()
end = datetime(2025,6,30).date()
mask = (
    df['Programme'].astype(str).str.strip().str.lower() == 'maternal & child health'
) & df['date_parsed'].notna() & (df['date_parsed'] >= start) & (df['date_parsed'] <= end)

filtered = df[mask]
total = filtered['amount_parsed'].sum()
print('rows', len(filtered))
print(filtered[['Disbursement Date','date_parsed','Amount','amount_parsed']])
print('total', total)
PY"
